import gzip
import re

def parse_geo_matrix_metadata(filepath):
    samples = {}
    with gzip.open(filepath, 'rt') as f:
        for line in f:
            if line.startswith('!Sample_title'):
                titles = line.strip().split('\t')[1:]
            elif line.startswith('!Sample_geo_accession'):
                accessions = line.strip().split('\t')[1:]
            elif line.startswith('!Sample_characteristics_ch1'):
                chars = line.strip().split('\t')[1:]
                if 'characteristics' not in samples:
                    samples['characteristics'] = chars
                else:
                    samples['characteristics'] = [samples['characteristics'][i] + " ; " + chars[i] for i in range(len(chars))]

    for i, acc in enumerate(accessions):
        accessions[i] = acc.strip('"')
        titles[i] = titles[i].strip('"')
        # if characteristics are available, strip them too
    return list(zip(accessions, titles, samples.get('characteristics', [''] * len(accessions))))

